  const arr=D.heroes.filter(h=>{if(role&&h.role!==role)return false;const p=LIB[h.id]||{};const general=[h.name,String(h.id),String(h.id).padStart(3,'0'),h.role,collabHeroIds.has(h.id)?'コラボ コラボヒーロー コラボキャラ コラボレーション':'オリジナル オリジナルヒーロー オリジナルキャラ'];const combat=[h.summary,h.cardKnowledge?.primary,h.cardKnowledge?.optional,...(h.practicalCompetency?.mainActions||[])];const fields={basic:[publicProfile(h).basic,p.basic],personality:[publicPersonality(h),p.personality],appearance:[p.appearance,p.impression],combat:[...combat,rangeDisplay(h),daDisplay(h),hsInfo(h)?.effect,hsInfo(h)?.hsName,hsCharge(h)]};const content=norm([...general,...(scope?(fields[scope]||[]):Object.values(fields).flat())].join(' '));return terms.every(t=>['コラボ','コラボヒーロー','コラボキャラ','コラボレーション'].includes(t)?collabHeroIds.has(h.id):['オリジナル','オリジナルヒーロー','オリジナルキャラ'].includes(t)?!collabHeroIds.has(h.id):content.includes(t));});
